WITH ссылка AS (SELECT d.entity_kind AS ok, d.entity_name AS oi, x[1] AS текст, x[2] AS цель FROM project_documents d CROSS JOIN LATERAL regexp_matches(d.content, '\[([^]\n]{1,160})\]\(([^)\s]+)\)', 'g') AS x WHERE d.project_id = $1), разбор AS (SELECT ok, oi, текст, цель, lower(regexp_replace(regexp_replace(текст, '^[`*]+|[`*]+$', '', 'g'), '^.*/|[.]md$', '', 'g')) AS сказано, split_part(цель, ':', 1) AS вид, lower(substring(цель from position(':' in цель) + 1)) AS имя FROM ссылка WHERE текст ~ '[.]md[`*]*$' AND текст ~ '/') SELECT ok || ' ' || oi || '  —  текст говорит «' || текст || '», а ссылка ведёт в ' || цель AS detail FROM разбор WHERE сказано <> вид AND сказано <> имя AND имя NOT LIKE '%/' || сказано AND NOT (сказано = 'readme' AND вид = 'index') ORDER BY 1
